#include "sys.h"
#include "delay.h"
#include "usart.h"
#include "bsp_adc.h"
//#include "bsp_advanced_timer.h"
#include "bsp_i2c_gpio.h"
#include "OLED_I2C.h"
#include "bsp_systick.h"
#include "bsp_led.h"
#include <math.h>
#include "OLED_I2C2.h"
uint8_t buf[20];
float f;
#define pi 3.1415926535
#define accur 0.015295//accur=18*3.3/4096��3.3/4096����ADC�������ȣ�18��Ϊ���ò���ת��һ���ܹ���ʾ���ʵ�λ�ӣ�
extern uint16_t ConvData;//ADC��������
extern unsigned char BMP1[];
int main()
{
	uint8_t x;
	LED_Init();
	INT_INIT ();
  delay_init();
	delay_ms(500);
	OLED_Init();					 /* OLED��ʼ�� */
	ADCx_Init();
//	AdvancedTim_Init();
	Before_State_Update(accur*ConvData);
	OLED_CLS();
	OLED_Init2();//OLED��ʼ��
	//OLED_Clear();//����     
  INT_MARK=0;	
	NVIC_PriorityGroupConfig(NVIC_PriorityGroup_2);
	while(1)
	{

		while(INT_MARK)
	{
			for(x=0;x<128;x=(x+1)%128)
			{
				OLED_DrawWave(x,(accur*ConvData));//���Ǹ������εĺ���
				//֮ǰд�˸����㺯������ʾ�Ĳ��β�������Ȼ���Ҿ͸���һ�»��㺯������������Ļ�Ͼ�������
				if(!INT_MARK){ OLED_CLS(); break;}
			}
		 }
	while(!INT_MARK)
	{
			f=(ConvData-1890)*3.3/4095;
			if(f<0)f=0;
			sprintf(buf, "voltage:%1.3fV",f); //������ʾ����
			OLED_ShowCH(0,0,buf);
			delay_ms(200);
	}
	}
}

